import numpy as np
from .padding import get_output_shape

class MaxPool2D:
    """Max Pooling 2D layer."""

    def __init__(self, kernel_size: int, stride: int | None = None):
        self.kernel_size = kernel_size
        self.stride = stride if stride is not None else kernel_size

    def forward(self, x: np.ndarray) -> np.ndarray:
        """
        Forward pass of MaxPool2D.

        x: input of shape (batch_size, height, width, channels), dtype float64
        Returns: output of shape (batch_size, out_height, out_width, channels), dtype float64
        """
        batch_size, height, width, channels = x.shape
        out_h, out_w = get_output_shape((height, width), self.kernel_size, self.stride, 0)

        output = np.zeros((batch_size, out_h, out_w, channels), dtype=np.float64)

        for b in range(batch_size):
            for c in range(channels):
                x_slice = x[b, :, :, c]
                for y in range(out_h):
                    for x_out in range(out_w):
                        i_start = y * self.stride
                        j_start = x_out * self.stride
                        patch = x_slice[i_start:i_start + self.kernel_size, j_start:j_start + self.kernel_size]
                        output[b, y, x_out, c] = np.max(patch)

        return output.astype(np.float64)

class AvgPool2D:
    """Average Pooling 2D layer."""

    def __init__(self, kernel_size: int, stride: int | None = None):
        self.kernel_size = kernel_size
        self.stride = stride if stride is not None else kernel_size

    def forward(self, x: np.ndarray) -> np.ndarray:
        """
        Forward pass of AvgPool2D.

        x: input of shape (batch_size, height, width, channels), dtype float64
        Returns: output of shape (batch_size, out_height, out_width, channels), dtype float64
        """
        batch_size, height, width, channels = x.shape
        out_h, out_w = get_output_shape((height, width), self.kernel_size, self.stride, 0)

        output = np.zeros((batch_size, out_h, out_w, channels), dtype=np.float64)

        for b in range(batch_size):
            for c in range(channels):
                x_slice = x[b, :, :, c]
                for y in range(out_h):
                    for x_out in range(out_w):
                        i_start = y * self.stride
                        j_start = x_out * self.stride
                        patch = x_slice[i_start:i_start + self.kernel_size, j_start:j_start + self.kernel_size]
                        output[b, y, x_out, c] = np.mean(patch)

        return output.astype(np.float64)
